# Every hand-written page is the size a stranger reads, and the known defects list only
# open ones.
#
#     elixir scripts/doc-size.exs
#
# A page grows a section at a time, each one reasonable, until nobody reads it to the end;
# nothing else notices. So this fails when a Markdown file git knows about (tracked, or
# untracked and not ignored) passes 400 lines. Three kinds are not held to it:
# `PROTOCOL.md`, one contract a client author reads whole; a generated file, one whose
# first lines say `<!-- Generated by`; and `docs/history/`, records kept as they were
# written, which nobody is asked to read. A page that passes the line is split along its
# own headings, its sections moving to pages of their own with a stub left under each
# heading, so its anchors keep resolving.
#
# And `docs/developer/defects.md` lists open defects only. Its entries live on the pages
# of `docs/developer/defects/`, each a `### D<n> - <what> (<severity>)` heading followed by
# an item (a line starting `- `) for each thing still wrong; a fixer deletes an item when
# it is fixed or taken. An entry with no item is closed and belongs in
# `docs/history/defects-closed.md`, so this fails on one, on a row of the defects table
# naming an entry its page does not have, and on an entry the table has no row for.
#
# Exits non-zero naming every finding, as `file:line: what`.

defmodule DocSize do
  @root Path.expand("..", __DIR__)
  @limit 400
  @whole ["PROTOCOL.md"]
  @history "docs/history/"
  @defects "docs/developer/defects.md"
  @defect_pages "docs/developer/defects/"

  def main(_args) do
    files = markdown_files()
    findings = Enum.flat_map(files, &too_long/1) ++ defects(files)

    for finding <- findings, do: IO.puts(:stderr, finding)

    case findings do
      [] ->
        IO.puts("doc sizes hold: #{length(files)} Markdown files, none past #{@limit} lines")

      _ ->
        IO.puts(:stderr, "#{length(findings)} finding(s)")
        System.halt(1)
    end
  end

  defp too_long(file) do
    lines = file |> read() |> lines()
    exempt? = file in @whole or String.starts_with?(file, @history) or generated?(lines)

    if exempt? or length(lines) <= @limit,
      do: [],
      else: [
        "#{file}:#{@limit + 1}: #{length(lines)} lines, past #{@limit}: split it along its headings"
      ]
  end

  defp generated?(lines),
    do: lines |> Enum.take(10) |> Enum.any?(&String.contains?(&1, "<!-- Generated by"))

  # The table in defects.md against the entries on its pages.
  defp defects(files) do
    pages = Enum.filter(files, &String.starts_with?(&1, @defect_pages))
    entries = for page <- pages, entry <- entries(page), do: entry

    list = if @defects in files, do: @defects |> read() |> lines() |> Enum.with_index(1), else: []

    # The entries and the closed record each have a page of their own, not this one.
    astray =
      for {text, n} <- list,
          Regex.match?(~r/^### D\d+ - |^## (Taken|Won't fix|Checked and not a defect)\s*$/, text),
          do:
            "#{@defects}:#{n}: entries go on the pages of #{@defect_pages}, closed ones in #{@history}defects-closed.md"

    rows =
      if list != [] do
        list
        |> Enum.flat_map(fn {text, n} ->
          case Regex.run(~r/^\|\s*\[D(\d+)\]\(defects\/([^)#\s]+)/, text) do
            [_, number, page] -> [{String.to_integer(number), @defect_pages <> page, n}]
            nil -> []
          end
        end)
      else
        []
      end

    in_list = MapSet.new(rows, fn {number, page, _n} -> {number, page} end)
    on_pages = MapSet.new(entries, fn {number, page, _n, _items} -> {number, page} end)

    closed =
      for {number, page, n, 0} <- entries,
          do:
            "#{page}:#{n}: D#{number} has no open item: it is closed, move it to #{@history}defects-closed.md"

    unlisted =
      for {number, page, n, _items} <- entries,
          not MapSet.member?(in_list, {number, page}),
          do: "#{page}:#{n}: D#{number} has no row in #{@defects}"

    missing =
      for {number, page, n} <- rows,
          not MapSet.member?(on_pages, {number, page}),
          do: "#{@defects}:#{n}: D#{number} is not on #{page}"

    astray ++ closed ++ unlisted ++ missing
  end

  # {number, page, line, items} for each `### D<n>` entry on a page.
  defp entries(page) do
    page
    |> read()
    |> lines()
    |> Enum.with_index(1)
    |> Enum.reduce([], fn {text, n}, acc ->
      case {Regex.run(~r/^### D(\d+) - /, text), acc} do
        {[_, number], _} ->
          [{String.to_integer(number), page, n, 0} | acc]

        {nil, [{number, ^page, at, items} | rest]} ->
          cond do
            Regex.match?(~r/^\#{1,6} /, text) -> [{:done, number, page, at, items} | rest]
            String.starts_with?(text, "- ") -> [{number, page, at, items + 1} | rest]
            true -> acc
          end

        {nil, _} ->
          acc
      end
    end)
    |> Enum.map(fn
      {:done, number, page, at, items} -> {number, page, at, items}
      entry -> entry
    end)
    |> Enum.reverse()
  end

  defp read(file), do: File.read!(Path.join(@root, file))

  defp lines(text), do: text |> String.split(~r/\r?\n/) |> drop_last_empty()

  defp drop_last_empty(lines) do
    case List.last(lines) do
      "" -> Enum.drop(lines, -1)
      _ -> lines
    end
  end

  # Tracked, plus untracked and not ignored, so a new page is held to it before it is added.
  defp markdown_files do
    args = ["ls-files", "--cached", "--others", "--exclude-standard", "-z", "--", "*.md"]

    case System.cmd("git", args, cd: @root) do
      {out, 0} ->
        out
        |> String.split(<<0>>, trim: true)
        |> Enum.uniq()
        |> Enum.filter(&File.regular?(Path.join(@root, &1)))
        |> Enum.sort()

      {_out, status} ->
        IO.puts(:stderr, "git ls-files exited #{status} in #{@root}; this needs a git checkout")
        System.halt(2)
    end
  end
end

DocSize.main(System.argv())
